package io.tenvyr.control.engine;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.tenvyr.platform.*;
import java.net.URI;
import java.net.http.*;
import java.time.*;
import java.util.*;
import java.util.function.Consumer;
import static io.tenvyr.control.engine.EngineFacts.*;

/** Reconciliation derives all legal work from persisted facts; caller-provided completion context has no authority. */
public final class EngineService implements AgentAdapter.Handlers {
  private final PipelineService pipelines;public final ExecutionService executions;private final ResultInboxService inbox;private final AgentEventService events;private final DispatchOutboxService outbox;private final EngineRuntime runtime;private final Consumer<String> projection;
  public EngineService(PipelineService pipelines,ExecutionService executions,ResultInboxService inbox,AgentEventService events,DispatchOutboxService outbox,EngineRuntime runtime,Consumer<String> projection){this.pipelines=pipelines;this.executions=executions;this.inbox=inbox;this.events=events;this.outbox=outbox;this.runtime=runtime;this.projection=projection;}
  public ObjectNode startExecution(String pipelineId,JsonNode input)throws Exception{ObjectNode pipeline=pipelines.findOne(pipelineId);if(pipeline==null)throw new IllegalArgumentException("Pipeline with ID "+pipelineId+" not found.");ObjectNode execution=executions.createExecution(pipeline,input);reconcileExecution(execution.path("id").asText(),false);ObjectNode reloaded=executions.getExecution(execution.path("id").asText());if(reloaded==null)return execution;if(reloaded.path("status").asText().equals("PENDING"))return fail(reloaded.path("id").asText(),Json.object("error","No initial steps found without dependencies."));return reloaded;}
  public ObjectNode cancelExecution(String executionId)throws Exception{ObjectNode execution=executions.cancelExecution(executionId,"Execution cancelled by request");project(executionId);try{outbox.notifyCancel(executionId,execution.path("terminationReason").asText("Execution cancelled"));}catch(Exception ignored){}return execution;}
  public void resumeAfterResult(String executionId,String stepId)throws Exception{reconcileExecution(executionId,true);}
  public void reconcileExecution(String executionId)throws Exception{reconcileExecution(executionId,false);}public void reconcileExecution(String executionId,boolean projectTerminal)throws Exception{boolean progressed=false;Set<String> affected=new LinkedHashSet<>();for(int pass=0;pass<100;pass++){boolean made=reconcilePass(executionId,affected);progressed|=made;if(!made)break;}if(progressed)project(executionId);else if(projectTerminal){ObjectNode execution=executions.getExecution(executionId);if(execution!=null&&TERMINAL_EXECUTION.contains(execution.path("status").asText()))project(executionId);}for(String id:affected)if(!id.equals(executionId))reconcileExecution(id,true);}
  private boolean reconcilePass(String executionId,Set<String> affected)throws Exception{boolean advanced=executions.reconcileExecution(executionId);if(runtime.reconcileCoordination(executionId))return true;ObjectNode execution=executions.getExecution(executionId);if(execution==null||!execution.path("status").asText().equals("RUNNING")||!execution.hasNonNull("activePlanRevisionId"))return advanced;JsonNode configs=executions.getExecutionPlanSteps(execution),plan=Json.object("steps",configs);List<ObjectNode> logical=executions.getStepExecutions(executionId);for(ObjectNode step:logical)if(step.path("status").asText().equals("FAILED")){ObjectNode config=step(plan,step.path("stepId").asText());if(config!=null&&config.path("onFailure").asText().equals("continue"))continue;fail(executionId,Json.object("failedStep",step.get("stepId"),"error",step.path("error").asText("Step failed with stop policy."),"attempts",step.get("attempt"),"maxAttempts",step.get("maxAttempts")));return true;}if(logical.stream().anyMatch(s->s.path("status").asText().equals("CANCELLED"))){cancelExecution(executionId);return true;}
    boolean complete=!configs.isEmpty();for(JsonNode config:configs){ObjectNode row=logical.stream().filter(s->s.path("stepId").asText().equals(config.path("id").asText())).findFirst().orElse(null);if(row==null||!TERMINAL_STEP.contains(row.path("status").asText()))complete=false;}if(complete){if(runtime.completionHeld(executionId))return advanced;ObjectNode output=Json.object();for(ObjectNode row:logical)output.set(row.path("stepId").asText(),row.get("output"));executions.updateExecutionStatus(executionId,"COMPLETED",output);return true;}
    Instant now=Instant.now();boolean progressed=advanced;for(ObjectNode row:logical){String status=row.path("status").asText();Instant eligible=instant(row,status.equals("RETRYING")?"nextAttemptAt":"eligibleAt");if(!Set.of("READY","RETRYING").contains(status)||eligible!=null&&eligible.isAfter(now))continue;ObjectNode config=step(plan,row.path("stepId").asText());if(config==null)continue;JsonNode input;try{input=Templates.resolve(config.hasNonNull("input")?config.get("input"):Json.object(),Templates.context(execution.get("input"),logical));if(runtime.isVerifierStep(executionId,config.path("id").asText())){JsonNode context=runtime.buildVerifierInput(executionId,config.path("id").asText());ObjectNode verifier=Json.object("schemaVersion",1,"role","verifier","goal",execution.path("input").path("goal").isTextual()?execution.path("input").path("goal").asText():"","iterationNumber",context.path("iterationNumber"),"context",context,"outputContract",Json.object("schema","VerifierDecisionV1","instructions","Evaluate the iteration outcome and return a VerifierDecisionV1 JSON object with schemaVersion: 1, iterationId, iterationNumber, action (\"ACCEPT\", \"CONTINUE\", or \"FAIL\"), reason, and evidenceRefs."));if(context.has("workspace"))verifier.set("workspace",context.get("workspace"));input=verifier;}}catch(Exception error){fail(executionId,Json.object("failedStep",config.get("id"),"error","Input resolution failed: "+message(error)));return true;}
      long timeout=Templates.durationMs(config.get("timeout"));ExecutionService.Claim claim;try{claim=executions.claimRunnableStep(executionId,config,input,maxAttempts(config),timeout>0?Instant.now().plusMillis(timeout):null);}catch(AuthorityFailure failure){if(!failure.disposition.equals("projection_failed"))throw failure;fail(executionId,Json.object("failedStep",config.get("id"),"error","Context projection failed: "+failure.code));return true;}if(claim==null)continue;progressed=true;if(!claim.disposition().equals("claimed"))continue;try{DispatchOutboxService.Disposition disposition=outbox.dispatchAttempt(claim.attempt().path("id").asText());if(disposition.outcome().equals("terminal_failure"))affected.add(disposition.executionId());}catch(Exception ignored){/* The durable PENDING outbox and recovery retain retry authority. */}}
    return progressed;
  }
  public void result(ObjectNode result,ObjectNode transport)throws Exception{ResultInboxService.Application applied=inbox.apply(result,transport);if(applied.disposition().equals("applied")||applied.disposition().equals("duplicate"))reconcileExecution(applied.executionId(),true);}public void event(ObjectNode event,ObjectNode transport){events.apply(event,transport);}
  private ObjectNode fail(String id,ObjectNode output){ObjectNode row=executions.updateExecutionStatus(id,"FAILED",output);project(id);return row;}
  private void project(String id){try{projection.accept(id);}catch(RuntimeException ignored){}}
  public static Consumer<String> gatewayProjection(Map<String,String> environment){HttpClient client=HttpClient.newHttpClient();String url=environment.getOrDefault("GATEWAY_URL","http://127.0.0.1:3000");return id->{try{client.send(HttpRequest.newBuilder(URI.create(url+"/api/webhooks/execution-update")).timeout(Duration.ofSeconds(10)).header("Content-Type","application/json").POST(HttpRequest.BodyPublishers.ofString(Json.stringify(Json.object("executionId",id)))).build(),HttpResponse.BodyHandlers.discarding());}catch(Exception ignored){}};}
}
